with open(json_file) as f:
    data = json.load(f)

demos = data.get('pairs', [])
print(f"Found {len(demos)} demo pairs")

# Define the transform function
def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    for keyf in (lambda r,c:r-c, lambda r,c:r+c):
        lines={}
        for r in range(H):
            for c in range(W):
                if g[r][c]!=bg: lines.setdefault(keyf(r,c),[]).append((r,c))
